import{_ as t,b as i,c as a,g as o}from"./chunks/framework.86O3EbG5.js";const c=JSON.parse('{"title":"摄影师之眼","description":"","frontmatter":{"title":"摄影师之眼","subTitle":"观察世界的五种根基","author":"oasis","date":"2026-09-18T00:00:00.000Z","tags":["读书笔记"]},"headers":[],"relativePath":"articles/books/the-photographers-eye/1.md","filePath":"articles/books/the-photographers-eye/1.md"}'),s={name:"articles/books/the-photographers-eye/1.md"};function r(p,e,l,n,d,h){return i(),a("div",null,[...e[0]||(e[0]=[o('<p>这本书讲述摄影师如何观察世界；观察方式也随着摄影技术的发展而变化。</p><h2 id="事物本身" tabindex="-1">事物本身</h2><p>摄影的对象是事物。摄影师相信事物就是事实，摄影基于事实。</p><h2 id="边框" tabindex="-1">边框</h2><p>摄影是有边框的，需要摄影师进行取舍；取舍实际是在构图。</p><h2 id="时间" tabindex="-1">时间</h2><p>摄影技术发展后，快门、光圈等设备都进步了，从延迟摄影走到高速瞬间抓拍。这里有一个名词：<strong>瞬间美</strong>。</p><h2 id="有利位置" tabindex="-1">有利位置</h2><p>摄影师无法移动拍摄对象，但可以选择移动相机，从非常规角度看到事物的全貌。</p><h2 id="摄影师之眼的根基" tabindex="-1">摄影师之眼的根基</h2><p>摄影师之眼的根基由五部分构成：</p><ol><li>事物本身</li><li>细节</li><li>边框</li><li>时间</li><li>有利位置</li></ol>',12)])])}const b=t(s,[["render",r]]);export{c as __pageData,b as default};
